package com.holidayroster.availability.application;
import com.holidayroster.availability.domain.AvailabilityRecord; import com.holidayroster.availability.infrastructure.AvailabilityRepository; import com.holidayroster.organization.application.OrganizationService; import com.holidayroster.shared.security.OrganizationAuthorization; import java.time.*; import org.springframework.data.domain.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AvailabilityService { private final AvailabilityRepository records;private final OrganizationAuthorization auth;private final Clock clock;public AvailabilityService(AvailabilityRepository r,OrganizationAuthorization a,Clock c){records=r;auth=a;clock=c;} @Transactional(readOnly=true) public Page<AvailabilityRecord> list(Long employeeId,LocalDate from,LocalDate to,int page,int size,Authentication a){Long own=auth.ownEmployeeId(a);if(employeeId==null)employeeId=own;if(employeeId==null||(!employeeId.equals(own)&&!auth.isOrganizationScoped(a)))throw new AccessDeniedException("Availability scope is not granted.");return records.findByEmployeeIdAndStartDateLessThanEqualAndEndDateGreaterThanEqual(employeeId,to==null?LocalDate.MAX:to,from==null?LocalDate.MIN:from,PageRequest.of(page,size));} @Transactional public AvailabilityRecord create(AvailabilityRecord.Type t,LocalDate s,LocalDate e,String reason,String note,Authentication a){Long own=own(a);return records.save(new AvailabilityRecord(own,t,s,e,reason,note,Instant.now(clock)));} @Transactional public AvailabilityRecord update(long id,String tag,AvailabilityRecord.Type t,LocalDate s,LocalDate e,String reason,String note,Authentication a){AvailabilityRecord r=locked(id,a);version(tag,r.getRowVersion());try{r.update(t,s,e,reason,note,Instant.now(clock));return r;}catch(IllegalArgumentException x){throw new OrganizationService.OrganizationValidationException(x.getMessage());}} @Transactional public void withdraw(long id,String tag,Authentication a){AvailabilityRecord r=locked(id,a);version(tag,r.getRowVersion());try{r.withdraw(Instant.now(clock));}catch(IllegalArgumentException x){throw new OrganizationService.OrganizationValidationException(x.getMessage());}} private AvailabilityRecord locked(long id,Authentication a){AvailabilityRecord r=records.findByIdForUpdate(id).orElseThrow(()->new OrganizationService.OrganizationNotFound("Availability not found."));if(!r.getEmployeeId().equals(own(a)))throw new AccessDeniedException("Availability scope is not granted.");return r;} private Long own(Authentication a){Long id=auth.ownEmployeeId(a);if(id==null||!auth.hasPermission(a,"AVAILABILITY.MANAGE_OWN"))throw new AccessDeniedException("Availability management requires own scope.");return id;} private static void version(String v,long actual){if(v==null||!v.replace("\"","").equals(Long.toString(actual)))throw new OrganizationService.InvalidOrganizationState("If-Match version is stale.");}}
